pub const CATALOG_COUNT: usize = ENTRIES.len();

pub fn entries() -> Vec<CatalogEntry> {
    ENTRIES.to_vec()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_contains_500_unique_named_targets() {
        assert_eq!(ENTRIES.len(), 500);
        let mut ids = ENTRIES.iter().map(|entry| entry.id).collect::<Vec<_>>();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids.len(), 500);
        let mut names = ENTRIES.iter().map(|entry| entry.review).collect::<Vec<_>>();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), 500);
    }

    #[test]
    fn each_target_has_specific_nonempty_guidance() {
        assert!(ENTRIES.iter().all(|entry| !entry.subsystem.is_empty()));
        assert!(ENTRIES
            .iter()
            .all(|entry| entry.review.contains(entry.subsystem)));
        assert!(ENTRIES
            .iter()
            .all(|entry| entry.guidance.contains(entry.subsystem)));
    }
}
